#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <iridium/tch_c_demod.h>
// pydoc.h is automatically generated in the build directory
#include <tch_c_demod_pydoc.h>

void bind_tch_c_demod(py::module& m)
{

    using tch_c_demod    = ::gr::iridium::tch_c_demod;


    py::class_<tch_c_demod, gr::block, gr::basic_block,
        std::shared_ptr<tch_c_demod>>(m, "tch_c_demod", D(tch_c_demod))

        .def(py::init(&tch_c_demod::make),
           py::arg("shard_index") = 0,
           py::arg("shard_count") = 1,
           D(tch_c_demod,make)
        )
        




        
        .def("get_n_handled_bursts",&tch_c_demod::get_n_handled_bursts,       
            D(tch_c_demod,get_n_handled_bursts)
        )


        
        .def("get_n_access_ok_bursts",&tch_c_demod::get_n_access_ok_bursts,       
            D(tch_c_demod,get_n_access_ok_bursts)
        )


        
        .def("get_n_access_ok_sub_bursts",&tch_c_demod::get_n_access_ok_sub_bursts,       
            D(tch_c_demod,get_n_access_ok_sub_bursts)
        )


        .def("set_upstream_count",&tch_c_demod::set_upstream_count,
            py::arg("n"),
            D(tch_c_demod,set_upstream_count)
        )

        ;




}








